package dk.ulfen.dinosaurs.vehicle;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;

/** Vehicle data generated by the TypeScript pipeline (resource /dinosaurs/vehicles.json). */
public final class VehicleSpec {
	public String id;
	public float scale;
	public float width;
	public float height;
	public float speed;
	public float health;
	/** entity-space seat positions in blocks (+z forward); seat 0 drives */
	public List<List<Double>> seats;
	public boolean translucent;

	public static List<VehicleSpec> load() {
		try (var in = VehicleSpec.class.getResourceAsStream("/dinosaurs/vehicles.json")) {
			if (in == null) throw new IllegalStateException("missing /dinosaurs/vehicles.json - run `npm run build:java` first");
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), new TypeToken<List<VehicleSpec>>() {}.getType());
		} catch (java.io.IOException e) {
			throw new RuntimeException(e);
		}
	}
}
